from solution import all_Bits_Set_In_The_Given_Range


def test_issue_example_4_1_2():
    """Example: all_Bits_Set_In_The_Given_Range(4,1,2) is True."""
    assert all_Bits_Set_In_The_Given_Range(4, 1, 2) == True  # 4=0b100, bits 2,1 = 0,0 -> True


def test_issue_single_unset_bit():
    """Single unset bit in range means True."""
    assert all_Bits_Set_In_The_Given_Range(4, 1, 1) == True  # 4=0b100, bit 1 = 0 -> True


def test_issue_single_set_bit():
    """Single set bit in range means False."""
    assert all_Bits_Set_In_The_Given_Range(4, 3, 3) == False  # 4=0b100, bit 3 = 1 -> False


def test_issue_range_including_set_bit():
    """Range containing any set bit means False."""
    assert all_Bits_Set_In_The_Given_Range(4, 1, 3) == False  # 4=0b100, bits 3,2,1 = 1,0,0 -> False


def test_issue_adjacent_range_with_set_bit():
    """Adjacent range ending on a set bit means False."""
    assert all_Bits_Set_In_The_Given_Range(4, 2, 3) == False  # 4=0b100, bits 3,2 = 1,0 -> False


def test_issue_all_ones_range():
    """All bits set in range means not all unset."""
    assert all_Bits_Set_In_The_Given_Range(7, 1, 3) == False  # 7=0b111, bits 3,2,1 = 1,1,1 -> False


def test_issue_zero_n_all_unset():
    """Zero has all bits unset in any low range."""
    assert all_Bits_Set_In_The_Given_Range(0, 1, 3) == True  # 0=0b000, bits 3,2,1 = 0,0,0 -> True


def test_issue_low_range_unset_when_high_set():
    """Low range unset while higher bit set means True."""
    assert all_Bits_Set_In_The_Given_Range(8, 1, 3) == True  # 8=0b1000, bits 3,2,1 = 0,0,0 -> True


def test_issue_high_single_set_bit():
    """High single set bit in range means False."""
    assert all_Bits_Set_In_The_Given_Range(8, 4, 4) == False  # 8=0b1000, bit 4 = 1 -> False


def test_issue_middle_unset_bit():
    """Middle zero bit between ones means True for that position."""
    assert all_Bits_Set_In_The_Given_Range(5, 2, 2) == True  # 5=0b101, bit 2 = 0 -> True


def test_contract_true_result_is_bool():
    """Function returns a boolean value."""
    assert all_Bits_Set_In_The_Given_Range(4, 1, 2) is True  # 4=0b100, bits 2,1 = 0,0 -> True


def test_contract_keyword_call():
    """Function accepts (n, l, r) arguments."""
    assert all_Bits_Set_In_The_Given_Range(n=5, l=1, r=2) == False  # 5=0b101, bits 2,1 = 0,1 -> False
